param([Parameter(Mandatory=$true)][string]$ConfigPath)
$ErrorActionPreference="Stop";$cfg=Get-Content -Raw -Encoding UTF8 $ConfigPath|ConvertFrom-Json;$python=[string]$cfg.python_exe;$repoRoot=[string]$cfg.repo_root;$workspaceConfig=[string]$cfg.workspace_config;$prefix=[string]$cfg.task_prefix;$optimizerRoot=Join-Path $repoRoot "same_day_1445\live_optimizer";if(-not(Test-Path $repoRoot)){throw "repo_root does not exist: $repoRoot"};if(-not(Test-Path $workspaceConfig)){throw "workspace_config does not exist: $workspaceConfig"}
foreach($command in @('preclose','close','optimizer')){$taskCfg=$cfg.tasks.$command;if($null -eq $taskCfg){throw "missing task config: $command"};$taskName="$prefix-$command";$at=[DateTime]::ParseExact([string]$taskCfg.time,"HH:mm:ss",$null);$arguments="-m same_day_1445.live_optimizer.jobs.run_pipeline $command --optimizer-root `"$optimizerRoot`" --workspace-config `"$workspaceConfig`"";$action=New-ScheduledTaskAction -Execute $python -Argument $arguments -WorkingDirectory $repoRoot;$trigger=New-ScheduledTaskTrigger -Weekly -WeeksInterval 1 -DaysOfWeek Monday,Tuesday,Wednesday,Thursday,Friday -At $at;$settings=New-ScheduledTaskSettingsSet -StartWhenAvailable -MultipleInstances IgnoreNew;Register-ScheduledTask -TaskName $taskName -Action $action -Trigger $trigger -Settings $settings -Force|Out-Null;Write-Host "Installed $taskName at $($taskCfg.time)"}
